import{_ as l,a0 as p,w as d,s as o,ao as r,I as t,x as a,a1 as n,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"通過 find 命令找到你要找的東西 | LCTT x X-CMD","titleTemplate":false,"description":"通過 find 命令找到你要找的東西 | LCTT (202003) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"通過 find 命令找到你要找的東西 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"通過 find 命令找到你要找的東西 | LCTT (202003) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202003/20200219 How to find what you-re looking for on Linux with find","title":"通過 find 命令找到你要找的東西","tag":"202003","desc":""},"relativePath":"202003/20200219 How to find what you-re looking for on Linux with find.md","filePath":"[post].md"}'),h={name:"202003/20200219 How to find what you-re looking for on Linux with find.md"};function c(g,s,k,b,u,f){const e=p("Link");return d(),o("div",null,[s[15]||(s[15]=r(`<h1 id="通過-find-命令找到你要找的東西" tabindex="-1">通過 find 命令找到你要找的東西 <a class="header-anchor" href="#通過-find-命令找到你要找的東西" aria-label="Permalink to “通過 find 命令找到你要找的東西”">​</a></h1><blockquote><p>find 命令有巨多的選項可以幫助你準確定位你在 Linux 系統上需要尋找的文件。這篇文章討論了一系列非常有用的選項。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202003/06/113842txki5llopb5aagbt.jpg" alt=""></p><p>在 Linux 系統上有許多用於查找文件的命令，而你在使用它們時也有巨多的選項可以使用。</p><p>例如，你不僅可以通過文件的名稱來查找文件，還可以通過文件的所有者或者組、它們的創建時間、大小、分配的權限、最後一次訪問它們的時間、關聯的信息節點，甚至是文件是否屬於系統上不再存在的帳户或組等等來查找文件。</p><p>你還可以指定搜索從哪裏開始，搜索應該深入到文件系統的什麼位置，以及搜索結果將告訴你它所找到的文件的數量。</p><p>而所有這些要求都可以通過 <code>find</code> 命令來處理。</p><p>下面提供了根據這些要求查找文件的示例。在某些命令中，錯誤（例如試圖列出你沒有讀取權限的文件）輸出將被髮送到 <code>/dev/null</code>，以便我們不必查看它。或者，我們可以簡單地以 root 身份運行以避免這個問題。</p><p>請記住，還有更多的其他選項。這篇文章涵蓋了很多內容，但並不是 <code>find</code> 命令幫助你定位查找文件的所有方式。</p><h3 id="選擇起點" tabindex="-1">選擇起點 <a class="header-anchor" href="#選擇起點" aria-label="Permalink to “選擇起點”">​</a></h3><p>使用 <code>find</code>，你可以選擇一個起點或從你所在的位置開始。要選擇的搜索的起點，請在單詞 <code>find</code> 後輸入它。例如，<code>find /usr</code> 或 <code>find ./bin</code> 將在 <code>/usr</code> 目錄或當前位置下的 <code>bin</code> 目錄開始搜索，而 <code>find ~</code> 將在你的主目錄中開始搜索，即使你當前位於當前文件系統中的其他位置。</p><h3 id="選擇你要找的" tabindex="-1">選擇你要找的 <a class="header-anchor" href="#選擇你要找的" aria-label="Permalink to “選擇你要找的”">​</a></h3><p>最常用的搜索策略之一是按名稱搜索文件。這需要使用 <code>-name</code> 選項。</p><p>默認情況下，<code>find</code> 會顯示找到的文件的完整路徑。如果你在命令中添加 <code>-print</code>，你會看到同樣的結果。如果你想查看與文件相關的詳細信息—-例如：文件的長度、權限等，你需要在你的 <code>find</code> 命令的末尾添加 <code>-ls</code> 參數。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find ~/bin -name tryme</span></span>
<span class="line"><span>/home/shs/bin/tryme</span></span>
<span class="line"><span>$ find ~/bin -name tryme -print</span></span>
<span class="line"><span>/home/shs/bin/tryme</span></span>
<span class="line"><span>$ find ~/bin -name tryme -ls</span></span>
<span class="line"><span>   917528   4 -rwx------   1 shs    shs   139 Apr  8  2019 /home/shs/bin/tryme</span></span></code></pre></div><p>你也可以使用子字符串來查找文件。例如，如果你將上面示例中的 <code>tryme</code> 替換為 <code>try*</code>，你將會找到所有名稱以 <code>try</code> 開頭的文件。（LCTT 譯註：如果要使用通配符 <code>*</code> ，請將搜索字符串放到單引號或雙引號內，以避免通配符被 shell 所解釋）</p><p>按名稱查找文件可能是 <code>find</code> 命令最典型的用法，不過還有很多其他的方式來查找文件，並且有這樣做的需要。下面的部分展示瞭如何使用其他可用的方式。</p><p>此外，當按文件大小、組、索引節點等條件來搜索文件時，你需要確認找到的文件與你要查找的文件是否相匹配。使用 <code>-ls</code> 選項來顯示細節是非常有用。</p><h3 id="通過大小查找文件" tabindex="-1">通過大小查找文件 <a class="header-anchor" href="#通過大小查找文件" aria-label="Permalink to “通過大小查找文件”">​</a></h3><p>按大小查找文件需要使用 <code>-size</code> 選項並且對相應規範使用一點技巧。例如，如果你指定 <code>-size 189b</code>，你將找到 189 個塊大小的文件，而不是 189 個字節。（LCTT 譯註：如果不跟上單位，默認單位是 <code>b</code>。一個塊是 512 個字節大小，不足或正好 512 個字節將佔據一個塊。）對於字節，你需要使用 <code>--size 189c</code>（字符）。而且，如果你指定 <code>--size 200w</code> ，你將會找到 200 個“<ruby>字<rt>word</rt></ruby>”的文件——以“雙字節增量”為單位的字，而不是“我們互相談論的那些事情”中的單詞。你還可以通過以千字節（<code>k</code>）、兆字節（<code>M</code>）和千兆字節（<code>G</code>）為單位提供大小來查找文件。（LCTT 譯註：乃至還有 <code>T</code>、<code>P</code>）</p><p>大多數情況下，Linux 用户會搜索比選定大小要大的文件。例如，要查找大於 1 千兆字節的文件，你可以使用這樣的命令，其中 <code>+1G</code> 表示“大於 1 千兆字節”:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find -size +1G -ls 2&gt;/dev/null</span></span>
<span class="line"><span>  787715 1053976 -rw-rw-r-- 1 shs  shs  1079263432 Dec 21  2018 ./backup.zip</span></span>
<span class="line"><span>  801834 1052556 -rw-rw-r-- 1 shs  shs  1077809525 Dec 21  2018 ./2019/hold.zip</span></span></code></pre></div><h3 id="通過索引節點號查找文件" tabindex="-1">通過索引節點號查找文件 <a class="header-anchor" href="#通過索引節點號查找文件" aria-label="Permalink to “通過索引節點號查找文件”">​</a></h3><p>你可以通過用於維護文件元數據（即除文件內容和文件名之外的所有內容）的索引節點來查找文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find -inum 919674 -ls 2&gt;/dev/null</span></span>
<span class="line"><span>  919674  4 -rw-rw-r--  1 shs  shs   512 Dec 27 15:25 ./bin/my.log</span></span></code></pre></div><h3 id="查找具有特定文件所有者或組的文件" tabindex="-1">查找具有特定文件所有者或組的文件 <a class="header-anchor" href="#查找具有特定文件所有者或組的文件" aria-label="Permalink to “查找具有特定文件所有者或組的文件”">​</a></h3><p>按所有者或組查找文件也非常簡單。這裏我們使用 <code>sudo</code> 來解決權限問題。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo find /home -user nemo -name &quot;*.png&quot; -ls</span></span>
<span class="line"><span> 1705219  4 drwxr-xr-x  2 nemo nemo  4096 Jan 28 08:50 /home/nemo/Pictures/me.png</span></span></code></pre></div><p>在下面這個命令中，我們尋找一個被稱為 <code>admins</code> 的多用户組擁有的文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># find /tmp -group admins -ls</span></span>
<span class="line"><span>   262199      4 -rwxr-x---   1 dory     admins         27 Feb 16 18:57 /tmp/testscript</span></span></code></pre></div><h3 id="查找沒有所有者或組的文件" tabindex="-1">查找沒有所有者或組的文件 <a class="header-anchor" href="#查找沒有所有者或組的文件" aria-label="Permalink to “查找沒有所有者或組的文件”">​</a></h3><p>你可以使用如下命令所示的 <code>-nouser</code> 選項來查找不屬於當前系統上的任何用户的文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># find /tmp -nouser -ls</span></span>
<span class="line"><span>262204 4 -rwx------ 1 1016 1016 17 Feb 17 16:42 /tmp/hello</span></span></code></pre></div><p>請注意，該列表顯示了舊用户的 UID 和 GID，這清楚地表明該用户未在系統上定義。這種命令將查找帳户已從系統中刪除的用户創建在主目錄之外的文件，或者在用户帳户被刪除後而未被刪除的主目錄中創建的文件。類似地，<code>-nogroup</code> 選項也會找到這樣的文件，尤其是當這些用户是相關組的唯一成員時。</p><h3 id="按上次更新時間查找文件" tabindex="-1">按上次更新時間查找文件 <a class="header-anchor" href="#按上次更新時間查找文件" aria-label="Permalink to “按上次更新時間查找文件”">​</a></h3><p>在此命令中，我們在特定用户的主目錄中查找過去 24 小時內更新過的文件。<code>sudo</code> 用於搜索另一個用户的主目錄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo find /home/nemo -mtime -1</span></span>
<span class="line"><span>/home/nemo</span></span>
<span class="line"><span>/home/nemo/snap/cheat</span></span>
<span class="line"><span>/home/nemo/tryme</span></span></code></pre></div><h3 id="按上次更改權限的時間查找文件" tabindex="-1">按上次更改權限的時間查找文件 <a class="header-anchor" href="#按上次更改權限的時間查找文件" aria-label="Permalink to “按上次更改權限的時間查找文件”">​</a></h3><p><code>-ctime</code> 選項可以幫助你查找在某個參考時間範圍內狀態（如權限）發生更改的文件。以下是查找在最後一天內權限發生更改的文件的示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -ctime -1 -ls</span></span>
<span class="line"><span>   787987   4 -rwxr-xr-x   1 shs   shs     189 Feb 11 07:31 ./tryme</span></span></code></pre></div><p>請記住，顯示的日期和時間只反映了對文件內容進行的最後更新。你需要使用像 <code>stat</code> 這樣的命令來查看與文件相關聯的三個狀態（文件創建、修改和狀態更改）。</p><h3 id="按上次訪問的時間查找文件" tabindex="-1">按上次訪問的時間查找文件 <a class="header-anchor" href="#按上次訪問的時間查找文件" aria-label="Permalink to “按上次訪問的時間查找文件”">​</a></h3><p>在這個命令中，我們使用 <code>-atime</code> 選項查找在過去兩天內訪問過的本地 pdf 文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find -name &quot;*.pdf&quot; -atime -2</span></span>
<span class="line"><span>./Wingding_Invites.pdf</span></span></code></pre></div><h3 id="根據文件相對於另一個文件的時間來查找文件" tabindex="-1">根據文件相對於另一個文件的時間來查找文件 <a class="header-anchor" href="#根據文件相對於另一個文件的時間來查找文件" aria-label="Permalink to “根據文件相對於另一個文件的時間來查找文件”">​</a></h3><p>你可以使用 <code>-newer</code> 選項來查找比其他文件更新的文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -newer dig1 -ls</span></span>
<span class="line"><span>   786434     68 drwxr-xr-x  67 shs      shs         69632 Feb 16 19:05 .</span></span>
<span class="line"><span>  1064442      4 drwxr-xr-x   5 shs      shs          4096 Feb 16 11:06 ./snap/cheat</span></span>
<span class="line"><span>   791846      4 -rw-rw-r--   1 shs      shs           649 Feb 13 14:26 ./dig</span></span></code></pre></div><p>沒有相應的 <code>-older</code> 選項，但是你可以用 <code>! -newer</code> （即更舊）得到類似的結果，它們基本上一樣。</p><h3 id="按類型查找文件" tabindex="-1">按類型查找文件 <a class="header-anchor" href="#按類型查找文件" aria-label="Permalink to “按類型查找文件”">​</a></h3><p>通過文件類型找到一個文件，你有很多選項——常規文件、目錄、塊和字符文件等等。以下是文件類型選項列表:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>b      塊特殊文件（緩衝的）</span></span>
<span class="line"><span>c      字符特殊文件（無緩衝的）</span></span>
<span class="line"><span>d      目錄</span></span>
<span class="line"><span>p      命名管道（FIFO）</span></span>
<span class="line"><span>f      常規文件</span></span>
<span class="line"><span>l      符號鏈接</span></span>
<span class="line"><span>s      套接字</span></span></code></pre></div><p>這裏有一個尋找符號鏈接的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -type l -ls</span></span>
<span class="line"><span>   805717   0 lrwxrwxrwx   1 shs    shs    11 Apr 10  2019 ./volcano -&gt; volcano.pdf</span></span>
<span class="line"><span>   918552   0 lrwxrwxrwx   1 shs    shs     1 Jun 16  2018 ./letter -&gt; pers/letter2mom</span></span></code></pre></div><h3 id="限制查找的深度" tabindex="-1">限制查找的深度 <a class="header-anchor" href="#限制查找的深度" aria-label="Permalink to “限制查找的深度”">​</a></h3><p><code>-mindepth</code> 和 <code>-maxdepth</code> 選項控制在文件系統中搜索的深度（從當前位置或起始點開始）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find -maxdepth 3 -name &quot;*loop&quot;</span></span>
<span class="line"><span>./bin/save/oldloop</span></span>
<span class="line"><span>./bin/long-loop</span></span>
<span class="line"><span>./private/loop</span></span></code></pre></div><h3 id="查找空文件" tabindex="-1">查找空文件 <a class="header-anchor" href="#查找空文件" aria-label="Permalink to “查找空文件”">​</a></h3><p>在這個命令中，我們尋找空文件，但不進入目錄及其子目錄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -maxdepth 2 -empty -type f -ls</span></span>
<span class="line"><span>   917517      0 -rw-rw-r--   1 shs   shs      0 Sep 23 11:00 ./complaints/newfile</span></span>
<span class="line"><span>   792050      0 -rw-rw-r--   1 shs   shs      0 Oct  4 19:02 ./junk</span></span></code></pre></div><h3 id="按權限查找文件" tabindex="-1">按權限查找文件 <a class="header-anchor" href="#按權限查找文件" aria-label="Permalink to “按權限查找文件”">​</a></h3><p>你可以使用 <code>-perm</code> 選項查找具有特定權限集的文件。在下面的示例中，我們只查找常規文件（<code>-type f</code>），以避免看到符號鏈接，默認情況下符號鏈接被賦予了這種權限，即使它們所引用的文件是受限的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find -perm 777 -type f -ls</span></span>
<span class="line"><span>find: ‘./.dbus’: Permission denied</span></span>
<span class="line"><span>   798748      4 -rwxrwxrwx   1 shs      shs            15 Mar 28  2019 ./runme</span></span></code></pre></div><h3 id="使用查找來幫助你刪除文件" tabindex="-1">使用查找來幫助你刪除文件 <a class="header-anchor" href="#使用查找來幫助你刪除文件" aria-label="Permalink to “使用查找來幫助你刪除文件”">​</a></h3><p>如果使用如下命令，你可以使用 <code>find</code> 命令定位並刪除文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -name runme -exec rm {} \\;</span></span></code></pre></div><p><code>{}</code> 代表根據搜索條件找到的每個文件的名稱。</p><p>一個非常有用的選項是將 <code>-exec</code> 替換為 <code>-ok</code>。當你這樣做時，<code>find</code> 會在刪除任何文件之前要求確認。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -name runme -ok rm -rf {} \\;</span></span>
<span class="line"><span>&lt; rm ... ./bin/runme &gt; ?</span></span></code></pre></div><p>刪除文件並不是 <code>-ok</code> 和 <code>-exec</code> 能為你做的唯一事情。例如，你可以複製、重命名或移動文件。</p><p>確實有很多選擇可以有效地使用 <code>find</code> 命令，毫無疑問還有一些在本文中沒有涉及到。我希望你已經找到一些新的，特別有幫助的。</p><hr>`,71)),t("p",null,[s[1]||(s[1]=a("via: ",-1)),n(e,{href:"https://www.networkworld.com/article/3527420/how-to-find-what-you-re-looking-for-on-linux-with-find.html"},{default:i(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3527420/how-to-find-what-you-re-looking-for-on-linux-with-find.html",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=a("作者：",-1)),n(e,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),n(e,{href:"https://github.com/heguangzhi"},{default:i(()=>[...s[4]||(s[4]=[a("heguangzhi",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const w=l(h,[["render",c]]);export{y as __pageData,w as default};
